<script setup lang="ts">
import {ref,computed,onBeforeUnmount} from 'vue';import {api,ApiError} from '../api';import type {WorkTab} from '../stores';import Modal from '../components/Modal.vue';
const props=defineProps<{tab:WorkTab}>();const file=ref<File|null>(null),pending=ref<File|null>(null),preview=ref<any>(null),error=ref(''),message=ref(''),confirm=ref(false),conflict=ref(false),completed=ref(false),downloading=ref(false),page=ref(1);let requestId='';
props.tab.submitOnly=true;
const rows=computed(()=>preview.value?.rows||[]),pages=computed(()=>Math.max(1,Math.ceil(rows.value.length/100))),visible=computed(()=>rows.value.slice((page.value-1)*100,page.value*100));
const changed=computed(()=>rows.value.filter((r:any)=>r.previousBirthdays.some((old:any)=>old!==r.birthday)).length);
async function inspect(next:File){props.tab.busy=true;error.value='';message.value='';confirm.value=false;try{const form=new FormData();form.append('file',next);const result=await api('employee-birthdays',{method:'POST',body:form});file.value=next;preview.value=result;page.value=1;conflict.value=false;completed.value=false;requestId=crypto.randomUUID();props.tab.dirty=true;}catch(e){error.value=(e as Error).message;conflict.value=true;}finally{props.tab.busy=false;}}
function choose(event:Event){const input=event.target as HTMLInputElement,next=input.files?.[0];input.value='';if(!next)return;if(props.tab.dirty){pending.value=next;return;}void inspect(next);}
function replace(){const next=pending.value;pending.value=null;if(next)void inspect(next);}
async function save(){if(!preview.value?.valid||props.tab.busy||conflict.value||completed.value)return;confirm.value=false;props.tab.busy=true;error.value='';try{const result=await api('employee-birthdays',{method:'PUT',body:JSON.stringify({rows:rows.value,expected:preview.value.expected,requestId})});message.value=`已更新 ${result.employees} 位員工的生日（${result.records} 筆主檔）。`;completed.value=true;props.tab.dirty=false;}catch(e){error.value=(e as Error).message;conflict.value=e instanceof ApiError&&[400,403,409].includes(e.status);}finally{props.tab.busy=false;}}
function csvCell(value:unknown){let text=String(value??'');if(/^[=+\-@\t\r]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';}
async function template(){downloading.value=true;error.value='';try{const data=await api('employees');const csv='\uFEFF'+[['員編','姓名','生日(YYYY-MM-DD)'],...data.employees.map((e:any)=>[e.employee_code,e.employee_name,e.birthday||''])].map(row=>row.map(csvCell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='員工生日範本.csv';link.click();URL.revokeObjectURL(url);}catch(e){error.value=(e as Error).message;}finally{downloading.value=false;}}
onBeforeUnmount(()=>{delete props.tab.submitOnly;});
</script><template><header class="page-heading"><div><p class="eyebrow">組織與門市 / 員工管理</p><h1>員工生日匯入</h1><p>先核對預覽，再整批更新生日。</p></div><button :disabled="downloading||tab.busy" @click="template">{{downloading?'準備範本…':'下載 CSV 範本'}}</button></header><p v-if="error" role="alert" class="notice error">{{error}}</p><p v-if="message" role="status" class="notice">{{message}}</p><p v-if="tab.busy" role="status">正在處理，請稍候…</p><div class="import-controls"><label>上傳 UTF-8 CSV<input type="file" accept=".csv,text/csv" :disabled="tab.busy||confirm||!!pending" @change="choose"></label><button v-if="file" :disabled="tab.busy||confirm||!!pending" @click="inspect(file)">重新預覽目前檔案</button></div><p class="hint">欄位為員編、姓名、生日。生日可用 YYYY-MM-DD 或 YYYY/M/D；空白生日略過，不會清除原值。最多 10,000 列、5 MB。</p><p v-if="!preview">請下載範本、填寫生日後上傳。</p><section v-if="preview"><h2>{{file?.name}}</h2><p>{{rows.length}} 位待核對 · {{changed}} 位生日有變動 · 略過 {{preview.skipped}} 列空白生日</p><div v-if="preview.errors.length" class="notice error" role="alert"><strong>{{preview.errors.length}} 個問題，尚不能送出</strong><ul><li v-for="(issue,index) in preview.errors" :key="index">第 {{issue.row}} 列：{{issue.message}}</li></ul><p>請修正 CSV 後重新上傳，整批通過才會寫入。</p></div><p v-else-if="!rows.length" class="notice">沒有可更新的生日資料。</p><p v-if="conflict" class="notice">預覽已失效或未完成，請重新預覽或修正檔案後再確認。</p><div class="table-wrap"><table><thead><tr><th>來源列</th><th>員編</th><th>姓名</th><th>目前生日</th><th>匯入生日</th><th>變更</th></tr></thead><tbody><tr v-for="r in visible" :key="r.row"><td>{{r.row}}</td><td>{{r.employee_code}}</td><td>{{r.employee_name}}</td><td>{{r.previousBirthdays.map((d:any)=>d||'未填寫').join('、')||'無主檔'}}</td><td>{{r.birthday}}</td><td>{{r.previousBirthdays.some((d:any)=>d!==r.birthday)?'將更新':'相同'}}</td></tr></tbody></table></div><div class="pagination"><span>第 {{page}} / {{pages}} 頁</span><button :disabled="page===1" @click="page--">上一頁</button><button :disabled="page===pages" @click="page++">下一頁</button></div><div class="dialog-actions"><button v-if="!completed" class="primary" :disabled="!preview.valid||tab.busy||conflict||!!pending" @click="confirm=true">確認更新 {{rows.length}} 位員工生日</button></div></section><Modal v-if="confirm" title="確認更新員工生日" @cancel="confirm=false"><p>將依 {{file?.name}} 更新 {{rows.length}} 位員工生日，其中 {{changed}} 位與目前資料不同。</p><p>同員編的門市主檔會一併更新；只修改生日。</p><div class="dialog-actions"><button @click="confirm=false">返回核對</button><button class="primary" @click="save">確認送出</button></div></Modal><Modal v-if="pending" title="取代目前匯入內容" @cancel="pending=null"><p>目前尚未送出的預覽將由 {{pending.name}} 取代。</p><div class="dialog-actions"><button @click="pending=null">保留目前內容</button><button class="primary" @click="replace">預覽新檔案</button></div></Modal></template><style scoped>.import-controls{display:flex;gap:16px;flex-wrap:wrap;align-items:end;margin:24px 0}label{display:grid;gap:8px}input{max-width:100%}.hint{color:var(--muted);line-height:1.8}.table-wrap{overflow:auto}table{min-width:720px}h2{font-size:18px;overflow-wrap:anywhere}.notice ul{max-height:260px;overflow:auto;line-height:1.8}.pagination{display:flex;align-items:center;gap:12px;justify-content:flex-end;margin:16px 0}.pagination span{margin-right:auto}</style>
